const body = $json.body ?? $json;
const payload = body.payload ?? {};
const alertId = body.alert_id ?? body.id ?? payload.alert_id ?? 'unknown-alert';
const severity = String(body.severity ?? payload.severity ?? 'unknown').toLowerCase();
const title = body.title ?? payload.title ?? payload.reason ?? 'SOC alert';
const srcIp = body.src_ip ?? payload.src_ip ?? body.target ?? null;
const route = ['critical', 'high'].includes(severity) ? 'soc_hot_queue' : 'soc_watch_queue';
return [{
  json: {
    response: {
      ok: true,
      workflow: 'A11 SOC Local Automation',
      kind: 'alert_notification',
      alert_id: String(alertId),
      severity,
      route
    },
    audit: {
      actor: 'n8n',
      action: 'automation.notification_received',
      object_type: 'alert',
      object_id: String(alertId),
      outcome: 'success',
      detail: {
        workflow: 'A11 SOC Local Automation',
        severity,
        title,
        src_ip: srcIp,
        route,
        received_at: new Date().toISOString(),
        original_payload: body
      }
    }
  }
}];

const body = $json.body ?? $json;
const payload = body.payload ?? {};
const actionType = body.action_type ?? 'unknown_action';
const target = body.target ?? null;
const alertId = payload.alert_id ?? body.alert_id ?? target ?? 'unknown-action';
const allowedLocalActions = ['notify_soc', 'block_ip', 'isolate_host'];
const supported = allowedLocalActions.includes(actionType);
const outcome = supported ? 'success' : 'failed';
return [{
  json: {
    response: {
      ok: supported,
      mode: 'n8n_webhook',
      workflow: 'A11 SOC Local Automation',
      action_type: actionType,
      target,
      message: supported
        ? 'Action accepted by local n8n workflow and recorded in SOC audit.'
        : 'Unsupported action type for local n8n workflow.'
    },
    audit: {
      actor: 'n8n',
      action: 'automation.response_webhook',
      object_type: 'response_action',
      object_id: String(alertId),
      outcome,
      detail: {
        workflow: 'A11 SOC Local Automation',
        action_type: actionType,
        target,
        payload,
        received_at: new Date().toISOString(),
        supported
      }
    }
  }
}];
